mapper.select:
select r.id, r. security_id,r.staff_id,r.staff_badge,s.name staff_name, r.park_id,
s.job_id, s.job_name, s.comp_id, s.comp_name, s.dep_id, s.dep_name, s.create_time in_time
from smt_security_person_relation r
left join smt_staff s on r.staff_id = s.id


		and r.security_id = #{query.securityId}


		and r.staff_badge LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')


		and r.staff_name LIKE CONCAT(CONCAT('%',#{query.staffName}),'%')


		and r.park_id = #{query.parkId}


		and s.comp_id = #{query.buId}


		and s.dep_id = #{query.depId}

select r.id, r. security_id,r.staff_id,r.staff_badge,s.name staffName, r.park_id, s.job_id, s.job_name, s.comp_id, s.comp_name, s.dep_id, s.dep_name, s.create_time inTime from smt_security_person_relation r left join smt_staff s on r.staff_id = s.id
r.id in
#{item}

